//! Settings kept between runs in %APPDATA%\SigmaDesk\config.json (Parsec keeps its own in
//! %APPDATA%\Parsec\config.json, MECHANICS.md section 1).

use serde::{Deserialize, Serialize};
use sigmadesk::consts::{PEER_ID_LEN, REGISTRY_PORT};
use sigmadesk::random_id;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub server_url: String,
    pub email: String,
    pub session_id: String,
    pub user_name: String,
    /// This computer's id in the node list.
    pub peer_id: String,
    pub device_id: String,
    pub host_enabled: bool,
    pub host_name: String,
    pub host_desc: String,
    pub host_public: bool,
    pub max_guests: u32,
    /// This computer's RustDesk ID, sent with each heartbeat.
    pub rustdesk_id: String,
    pub rustdesk_path: String,
    pub id_server: String,
    pub relay_server: String,
    pub server_key: String,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            server_url: format!("http://127.0.0.1:{REGISTRY_PORT}"),
            email: String::new(),
            session_id: String::new(),
            user_name: String::new(),
            peer_id: random_id(PEER_ID_LEN),
            device_id: random_id(PEER_ID_LEN),
            host_enabled: false,
            host_name: std::env::var("COMPUTERNAME").unwrap_or_else(|_| "내 컴퓨터".into()),
            host_desc: String::new(),
            host_public: false,
            max_guests: 1,
            rustdesk_id: String::new(),
            rustdesk_path: String::new(),
            id_server: String::new(),
            relay_server: String::new(),
            server_key: String::new(),
        }
    }
}

fn path() -> PathBuf {
    let base = std::env::var("APPDATA").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from("."));
    base.join("SigmaDesk").join("config.json")
}

impl Config {
    pub fn load() -> Config {
        std::fs::read_to_string(path())
            .ok()
            .and_then(|t| serde_json::from_str(&t).ok())
            .unwrap_or_default()
    }

    pub fn save(&self) {
        let p = path();
        if let Some(dir) = p.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Ok(text) = serde_json::to_string_pretty(self) {
            let _ = std::fs::write(p, text);
        }
    }
}

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
//! SigmaDesk: a Parsec-style remote desktop app. Sign in, see your computers, press Connect.
//! Hosting registers this computer in the online list; the RustDesk engine does the streaming.

mod config;
mod engine;
mod net;
mod ui;

use eframe::egui;
use std::path::PathBuf;

pub struct Args {
    pub screenshot: Option<PathBuf>,
    pub demo: bool,
    pub link: Option<String>,
}

fn parse_args() -> Args {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut args = Args { screenshot: None, demo: false, link: None };
    let mut i = 0;
    while i < argv.len() {
        match argv[i].as_str() {
            "--screenshot" => {
                args.screenshot = argv.get(i + 1).map(PathBuf::from);
                i += 1;
            }
            "--demo" => args.demo = true,
            other => {
                if let Some(peer) = engine::link_target(other) {
                    args.link = Some(peer);
                }
            }
        }
        i += 1;
    }
    args
}

fn main() -> eframe::Result<()> {
    let args = parse_args();
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("SigmaDesk")
            .with_inner_size([1180.0, 740.0])
            .with_min_inner_size([820.0, 560.0]),
        ..Default::default()
    };
    eframe::run_native("SigmaDesk", options, Box::new(move |cc| Ok(Box::new(ui::App::new(cc, args)))))
}

